export async function resolveSession(
  token: string,
): Promise<SessionPrincipal | null> {
  const tokenHash = hashToken(token);
  const principal = await sessionRepo.findSessionByTokenHash(tokenHash);
  if (!principal?.activeOrgId) return principal;

  const org = await orgRepo.findOrgById(principal.activeOrgId);
  const member =
    org && org.archivedAt === null
      ? await memberRepo.findMember(org.id, principal.userId)
      : null;

  if (member && member.status === "active") return principal;

  await forgetDefaultOrg(principal.activeOrgId, principal.userId);
  return sessionRepo.findSessionByTokenHash(tokenHash);
}

/**
 * Stops sessions from defaulting to an org the person can no longer open.
 * When `userId` is omitted, every session pointed at the org is retargeted
 * (workspace deletion). Otherwise only that person's sessions move, and any
 * session already defaulting to a different workspace is left alone. The
 * replacement is another workspace they still belong to, or none.
 */
export async function forgetDefaultOrg(
  orgId: OrgId,
  userId?: UserId,
): Promise<void> {
  const rows = await sessionRepo.listSessionsByActiveOrg(orgId, userId);
  const fallback = new Map<UserId, OrgId | null>();

  for (const row of rows) {
    let next = fallback.get(row.userId);
    if (next === undefined) {
      const orgs = await orgRepo.listOrgsForUser(row.userId);
      next = orgs.find((item) => item.id !== orgId)?.id ?? null;
      fallback.set(row.userId, next);
    }
    await sessionRepo.setActiveOrgOrClear(row.id, next);
  }
}

const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

await forgetDefaultOrg(input.orgId, removed.userId);

await emit("member.removed", {

  const archived = await orgRepo.archiveOrg(input.orgId);
  await forgetDefaultOrg(input.orgId);
  return archived;
}

